"""Lab progress: a git-ignored JSON record, plus the generated file the doc site reads."""

from __future__ import annotations

import json
import os
from datetime import datetime
from pathlib import Path

LABS_DIR = Path(__file__).resolve().parents[1]
PROGRESS = LABS_DIR / ".progress.json"
SITE_PROGRESS = LABS_DIR.parent / "site" / "assets" / "progress.js"


def disabled() -> bool:
    """Nothing is recorded during self-tests or when a reference solution is being run."""
    return bool(os.environ.get("LABS_NO_RECORD")) or "solutions" in Path.cwd().parts


def load() -> dict:
    try:
        return json.loads(PROGRESS.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}


def _save(data: dict) -> None:
    PROGRESS.write_text(json.dumps(data, indent=2, sort_keys=True), encoding="utf-8")


def task_passed(lab_id: str, task: str, note: str | None = None) -> None:
    if disabled():
        return
    data = load()
    entry = data.setdefault(lab_id, {}).setdefault("tasks", {})
    entry[task] = {"at": datetime.now().isoformat(timespec="seconds"), **({"note": note} if note else {})}
    _save(data)


def tasks_done(lab_id: str) -> set[str]:
    return set(load().get(lab_id, {}).get("tasks", {}))


def write_site_progress(status: dict[str, dict]) -> None:
    """status: {lab_id: {"passed": bool, "detail": str}} for every code lab."""
    SITE_PROGRESS.write_text(
        "// Lab pass state. Generated by `python -m labs status`; do not edit by hand.\n"
        "window.LAB_PROGRESS = " + json.dumps(status, indent=2, sort_keys=True) + ";\n",
        encoding="utf-8",
        newline="\n",
    )
